from __future__ import annotations

import logging
import pathlib
import re
import socket
import subprocess
import time

import psutil
from taf.transport.ssh import SSHConnection  # type: ignore[import-untyped]

from taf.ul.ue.sim.env_setup.utils.ssh_utils import get_ssh


def resolve_to_ip(host: str) -> str:
    try:
        return socket.gethostbyname(host)
    except socket.error as err:
        logging.getLogger(__name__).warning(f"Failed to resolve {host} to IP: {err}")
        return host


def get_time_diff(start_time: float, max_timeout: float) -> float:
    now = time.time()
    return max_timeout - (now - start_time)


def opt_bool(val):
    try:
        return str(val).lower().strip() == "true"
    except Exception:
        return False


def get_ip_address(ifname: str, ip_protocol_version: str | None = "4") -> str:
    inet = "inet" if ip_protocol_version == "4" else "inet6"
    ip_addr_regex = re.compile(rf"(?<={inet} )(.*)(?=/)", re.M)
    ip_output = subprocess.check_output(["ip", "addr", "show", ifname], text=True)
    ips = ip_addr_regex.findall(ip_output)
    return ips[0]


def kill_configuration_process() -> None:
    time.sleep(1)
    for proc in (proc for proc in psutil.process_iter() if proc.status() != psutil.STATUS_ZOMBIE):
        if "configuration_manager.py" in " ".join(proc.cmdline()):
            proc.terminate()
            time.sleep(1)
            if proc.is_running():
                proc.kill()


def is_path_the_same(src: str | pathlib.Path, dst: str | pathlib.Path, logger: logging.Logger) -> bool:
    if isinstance(src, str):
        src = pathlib.Path(src)
    if isinstance(dst, str):
        dst = pathlib.Path(dst)
    try:
        from hashlib import sha256

        src_sha256 = sha256(src.read_bytes())
        dst_sha256 = sha256(dst.read_bytes())
        return src_sha256.hexdigest() == dst_sha256.hexdigest()
    except FileNotFoundError as err:
        logger.debug(err)
    except Exception as err:
        logger.warning(f"Couldn't check if files are the same. Going to copy. {src = } -> {dst = }. EXC: {err}")
    return False


def get_pingable_lmp_ip(lmp_ip, lmp_ips: list[str], remote_host: str, logger: logging.Logger) -> str:
    with get_ssh(remote_host, "ute", "ute", timeout=10, logger=logger) as ssh_connection:
        lmp_ip = "192.168.255.129" if lmp_ip == "192.168.255.1" else "192.168.255.119" if lmp_ip == "192.168.255.7" else lmp_ip
        lmp_ips.insert(0, lmp_ips.pop(lmp_ips.index(lmp_ip)) if lmp_ip in lmp_ips else lmp_ip)
        for ip_addr in lmp_ips:
            logger.debug(f"Checking '{ip_addr}' address on {remote_host}.")
            if is_host_available(ssh_connection, ip_addr, logger):
                logger.debug(f"Checking '{ip_addr}' address on {remote_host} - OK.")
                return ip_addr
    ip_addr = "192.168.255.129"
    logger.error(f"No LMP IP address is pingable! Going to use try {ip_addr} as recovery")
    return ip_addr


def is_host_available(connection: SSHConnection, host: str, logger: logging.Logger) -> bool:
    """Check if the host is available via nmap over SSH."""
    output = connection.execute(f"nmap -n -sP -oG - -PR {host}", timeout=5)
    logger.debug(output)
    return "1 host up" in output
